# Set up a working tree from a fresh clone.
#
#   .\setup.ps1                # fetch engine + libchdr, apply the project's engine patches, build
#   .\setup.ps1 -SkipBuild     # fetch, patch and install only
#
# You still supply the game: a .gdi dump of Draconus: Cult of the Wyrm (USA, V1.000).
# Nothing from the disc is downloaded, committed or generated by this script.
param(
    [switch]$SkipBuild,
    [string]$Sdl3Dir = "",
    [string]$VcVars = ""
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$engine = Join-Path $root "engine"
$dl = Join-Path $root "work\dl"

function Find-VisualStudio {
    param([string]$Explicit)
    if ($Explicit) {
        if (Test-Path -LiteralPath $Explicit) { return $Explicit }
        throw "vcvars64.bat not found: $Explicit"
    }
    $programFilesX86 = ${env:ProgramFiles(x86)}
    if (-not $programFilesX86) { $programFilesX86 = "C:\Program Files (x86)" }
    if ($programFilesX86) {
        $vswhere = Join-Path $programFilesX86 "Microsoft Visual Studio\Installer\vswhere.exe"
        if (Test-Path -LiteralPath $vswhere) {
            $found = (& $vswhere -latest -products * `
                      -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 `
                      -property installationPath 2>$null | Select-Object -First 1)
            if ($found) {
                $candidate = Join-Path $found.Trim() "VC\Auxiliary\Build\vcvars64.bat"
                if (Test-Path -LiteralPath $candidate) { return $candidate }
            }
        }
    }
    foreach ($candidate in @(
        "C:\Program Files\Microsoft Visual Studio\2022\Community\VC\Auxiliary\Build\vcvars64.bat",
        "C:\Program Files\Microsoft Visual Studio\2022\Professional\VC\Auxiliary\Build\vcvars64.bat",
        "C:\Program Files\Microsoft Visual Studio\2022\Enterprise\VC\Auxiliary\Build\vcvars64.bat",
        "C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\VC\Auxiliary\Build\vcvars64.bat")) {
        if (Test-Path -LiteralPath $candidate) { return $candidate }
    }
    throw ("MSVC x64 build tools not found. Install Visual Studio 2022 Build Tools with the " +
           "'Desktop development with C++' workload, or pass -VcVars <path to vcvars64.bat>.")
}

function Resolve-CMake {
    param([string]$VisualStudio)
    $cmd = Get-Command cmake -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $vsRoot = $VisualStudio -replace '\\VC\\Auxiliary\\Build\\vcvars64\.bat$', ''
    $candidate = Join-Path $vsRoot "Common7\IDE\CommonExtensions\Microsoft\CMake\CMake\bin\cmake.exe"
    if (Test-Path -LiteralPath $candidate) { return $candidate }
    throw "cmake not found; install CMake or the Visual Studio CMake component."
}

function Resolve-Ninja {
    param([string]$VisualStudio)
    $cmd = Get-Command ninja -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    $vsRoot = $VisualStudio -replace '\\VC\\Auxiliary\\Build\\vcvars64\.bat$', ''
    $candidate = Join-Path $vsRoot "Common7\IDE\CommonExtensions\Microsoft\CMake\Ninja\ninja.exe"
    if (Test-Path -LiteralPath $candidate) { return $candidate }
    throw "ninja not found; install Ninja or the Visual Studio CMake component."
}

# Later patches touch the same files as earlier ones, so a reverse-check of an earlier patch can
# fail on an already-patched tree. These are the distinct features each patch adds; if all are
# present the tree is already the pinned engine plus the patch set. A marker written after a
# successful run makes the common re-run path a file read instead of this guess.
function Test-EnginePatchMarkersBase {
    $markers = @(
        (Test-Path -LiteralPath (Join-Path $engine "render\include\dream\render\present_rate.h")),
        (Test-Path -LiteralPath (Join-Path $engine "render\include\dream\render\interpolate.h")),
        (Test-Path -LiteralPath (Join-Path $engine "render\include\dream\render\input.h")) -and
            [bool](Select-String -LiteralPath (Join-Path $engine "render\include\dream\render\input.h") `
                    -Pattern 'enum class InputPreset' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "translator\src\analysis\discover.cpp") `
                    -Pattern 'kPlausibleEntryScan' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "render\include\dream\render\overlay.h") `
                    -Pattern 'text_rects' -Quiet),
        (Test-Path -LiteralPath (Join-Path $engine "runtime\include\dream\runtime\hash\sha1.h"))
    )
    return -not ($markers -contains $false)
}

function Test-EnginePatchMarkers {
    if (-not (Test-EnginePatchMarkersBase)) { return $false }
    # 0006 onward postdate the feature list above, so each has its own probe; a tree that stops
    # short of one must not be mistaken for a fully patched tree.
    $late = @(
        [bool](Select-String -LiteralPath (Join-Path $engine "runtime\boot\boot_main.cpp") `
                    -Pattern 'wmain|WideCharToMultiByte' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "render\src\vk\window.cpp") `
                    -SimpleMatch 'SDL_GetPrefPath("", "dream-recomp")' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "runtime\boot\boot_main.cpp") `
                    -SimpleMatch 'present-rate takes a rate in Hz' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "render\src\vk\window.cpp") `
                    -SimpleMatch 'could not migrate' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "render\src\vk\window.cpp") `
                    -SimpleMatch 'The requested content rate can be higher than the panel' -Quiet),
        [bool](Select-String -LiteralPath (Join-Path $engine "render\include\dream\render\vk\context.h") `
                    -SimpleMatch 'create_device' -Quiet)
    )
    return -not ($late -contains $false)
}

# The engine is pinned to the commit this project was developed against.
$EngineUrl = "https://codeload.github.com/phobos665/dream-recomp/zip/51ca2766d2ebeae9caacda4e305eacb88cf64013"
$EnginePin = "51ca2766d2ebeae9caacda4e305eacb88cf64013"

# libchdr is the engine's only submodule. Pin its commit too: a source build must not depend on
# whatever master happens to contain on the day it is run.
$LibchdrPin = "47d794151b2b64f6aba60304e6480f4f5a2bc24b"
$LibchdrUrl = "https://codeload.github.com/rtissera/libchdr/zip/$LibchdrPin"

function Get-Zip($url, $dest) {
    New-Item -ItemType Directory -Force $dl | Out-Null
    $zip = Join-Path $dl ((Split-Path $dest -Leaf) + ".zip")
    curl.exe -L --fail --silent --show-error -o $zip $url
    if ($LASTEXITCODE -ne 0) { throw "download failed: $url" }
    $tmp = Join-Path $dl ((Split-Path $dest -Leaf) + "-src")
    if (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }
    Expand-Archive -LiteralPath $zip -DestinationPath $tmp -Force
    $inner = Get-ChildItem $tmp -Directory | Select-Object -First 1
    New-Item -ItemType Directory -Force $dest | Out-Null
    Copy-Item (Join-Path $inner.FullName "*") $dest -Recurse -Force
}

if (-not (Test-Path (Join-Path $engine "CMakeLists.txt"))) {
    Write-Host "fetching dream-recomp @ $EnginePin"
    Get-Zip $EngineUrl $engine
}
if (-not (Test-Path (Join-Path $engine "third_party\libchdr\CMakeLists.txt"))) {
    Write-Host "fetching libchdr"
    Get-Zip $LibchdrUrl (Join-Path $engine "third_party\libchdr")
}

# Our title configuration lives in this repository, outside the engine, so an engine update
# never overwrites it. Per-game extracted data is not copied: it is the owner's. The disc image
# is the one line setup must not reset: the owner configured it with import-disc, and re-running
# setup after that has to keep it.
foreach ($game in Get-ChildItem (Join-Path $root "game") -Directory) {
    $target = Join-Path $engine "games\$($game.Name)"
    New-Item -ItemType Directory -Force $target | Out-Null
    $targetToml = Join-Path $target "$($game.Name).toml"
    $importedImage = $null
    if (Test-Path $targetToml) {
        $line = Select-String -LiteralPath $targetToml -Pattern '^\s*image\s*=\s*"(.*)"' |
                Select-Object -First 1
        if ($line -and $line.Matches[0].Groups[1].Value -notlike "CHANGE-ME*") {
            $importedImage = $line.Line
        }
    }
    Copy-Item (Join-Path $game.FullName "*.toml") $target -Force
    Copy-Item (Join-Path $game.FullName "CMakeLists.txt") $target -Force
    if ($importedImage) {
        $text = Get-Content $targetToml -Raw
        $text = [regex]::Replace($text, '(?m)^[ \t]*image[ \t]*=.*$',
                                 [System.Text.RegularExpressions.MatchEvaluator] {
                                     param($match) $importedImage
                                 })
        Set-Content -LiteralPath $targetToml -Value $text -NoNewline
        Write-Host "kept imported disc for games\$($game.Name)"
    }
    Write-Host "installed title config: games\$($game.Name)"
}

# The engine is fetched pristine; the project's changes are in patches/ (docs/ENGINE-CHANGES.md).
# Re-running is safe. Later patches touch the same files as earlier ones (0005 and 0001 both edit
# boot_main.cpp), so a reverse-check of 0001 on a fully patched tree can fail even though 0001 is
# applied. The marker written after a successful run is the fast path; the feature markers are the
# fallback for a tree that predates the marker.
if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    throw "git is required to apply the engine patches (patches/)"
}
$patches = @(Get-ChildItem (Join-Path $root "patches") -Filter *.patch -ErrorAction SilentlyContinue |
             Sort-Object Name)
$patchNames = ($patches | ForEach-Object { $_.Name }) -join "`n"
$patchMarker = Join-Path $engine ".draconus-patches"
$patchesApplied = $false
$appliedNames = @()
if (Test-Path -LiteralPath $patchMarker) {
    $recorded = Get-Content -LiteralPath $patchMarker -Raw
    if ($recorded) {
        foreach ($patch in $patches) {
            if ($recorded.Contains($patch.Name)) { $appliedNames += $patch.Name }
        }
    }
    if ($appliedNames.Count -eq $patches.Count) {
        Write-Host "engine patches already applied (marker)"
        $patchesApplied = $true
    }
}
if (-not $patchesApplied -and $appliedNames.Count -eq 0 -and (Test-EnginePatchMarkers)) {
    Write-Host "engine patches already applied (engine markers)"
    $patchesApplied = $true
}
if (-not $patchesApplied -and $appliedNames.Count -eq 0 -and (Test-EnginePatchMarkersBase)) {
    # A tree set up before the 0006 marker existed: patches 0001-0005 are present, so 0006 and
    # everything after it still has to be applied. Do not let the 0001 reverse-check failure stand
    # in their way.
    $appliedNames = @($patches | Where-Object { $_.Name -lt "0006" } |
                      ForEach-Object { $_.Name })
    Write-Host "engine base patches already applied (engine markers)"
}
if (-not $patchesApplied) {
    Push-Location $root
    try {
        foreach ($patch in $patches) {
            if ($appliedNames -contains $patch.Name) {
                Write-Host "engine patch already applied: $($patch.Name)"
                continue
            }
            # A patch that does not match makes git write to stderr; run it through cmd so
            # Windows PowerShell 5.1 does not turn that into a terminating NativeCommandError.
            & cmd /c "git apply --check --directory=engine `"$($patch.FullName)`" 2>nul"
            if ($LASTEXITCODE -eq 0) {
                & cmd /c "git apply --directory=engine `"$($patch.FullName)`" 2>nul"
                if ($LASTEXITCODE -ne 0) { throw "could not apply $($patch.Name)" }
                Write-Host "applied engine patch: $($patch.Name)"
                $appliedNames += $patch.Name
            } else {
                & cmd /c "git apply --reverse --check --directory=engine `"$($patch.FullName)`" 2>nul"
                if ($LASTEXITCODE -eq 0) {
                    Write-Host "engine patch already applied: $($patch.Name)"
                    $appliedNames += $patch.Name
                } elseif (Test-EnginePatchMarkers) {
                    # A later patch has moved the context of an earlier one; the feature markers
                    # prove the whole set is present.
                    Write-Host "engine patches already applied (engine markers)"
                    $patchesApplied = $true
                    break
                } else {
                    throw ("$($patch.Name) neither applies nor is already applied.`n" +
                           "The engine tree is not the pinned commit plus these patches; " +
                           "see patches/README.md.")
                }
            }
        }
    } finally {
        Pop-Location
    }
}
$markerText = "engine pin: $EnginePin`npatches:`n$patchNames`n"
[System.IO.File]::WriteAllText($patchMarker, $markerText, (New-Object System.Text.UTF8Encoding($false)))

if ($SkipBuild) {
    Write-Host "`nnext: tools\import-disc.bat `"D:\path\to\draconus.gdi`", then re-run .\setup.ps1"
    return
}

# The build translates the extracted boot executable. It is the owner's data and never committed,
# so a fresh clone has to produce it from the disc it imported.
$toml = Join-Path $engine "games\draconus\draconus.toml"
$binary = Join-Path $engine "games\draconus\extracted\fs\1ST_READ.BIN"
if (-not (Test-Path $binary)) {
    $image = $null
    if (Test-Path $toml) {
        $line = Select-String -LiteralPath $toml -Pattern '^\s*image\s*=\s*"(.*)"' | Select-Object -First 1
        if ($line) { $image = $line.Matches[0].Groups[1].Value }
    }
    if ($image -and $image -notlike "CHANGE-ME*" -and (Test-Path -LiteralPath $image)) {
        if ($image -match '\.chd$') {
            throw ("the build needs a GDI dump: dracdisc extract reads GDI track data and does " +
                   "not decode CHD. The release runtime can read a CHD, but to build the " +
                   "translated executable from source, convert it with chdman (for example " +
                   "chdman extractcd -i game.chd -o game.gdi) or import a GDI. See " +
                   "docs/09-TOOLING.md.")
        }
        if (-not (Get-Command python -ErrorAction SilentlyContinue)) {
            throw "Python 3.9+ is required to extract the boot executable (python was not found on PATH)."
        }
        Write-Host "extracting the boot executable from the configured dump"
        Push-Location (Join-Path $root "tools\draconus-disc")
        try {
            python -m dracdisc extract $image -o (Join-Path $engine "games\draconus\extracted\fs")
            if ($LASTEXITCODE -ne 0) { throw "extraction failed" }
        } finally {
            Pop-Location
        }
    }
}
if (-not (Test-Path $binary)) {
    Write-Host ""
    Write-Host "No extracted boot executable yet, so there is nothing to translate:"
    Write-Host "  1. tools\import-disc.bat `"D:\path\to\draconus.gdi`""
    Write-Host "  2. re-run .\setup.ps1"
    return
}

$vc = Find-VisualStudio $VcVars
$cmake = Resolve-CMake $vc
$ninja = Resolve-Ninja $vc
# cmake -G Ninja looks for ninja on PATH; a Visual Studio install keeps it beside CMake, which is
# not normally on PATH.
$env:PATH = (Split-Path -Parent $ninja) + ";" + $env:PATH

# A local SDL3 build is what this project used; anywhere else, pass -Sdl3Dir or install SDL3.
if (-not $Sdl3Dir) {
    $localSdl = Join-Path $root "work\sdl3\cmake"
    if (Test-Path (Join-Path $localSdl "SDL3Config.cmake")) {
        $Sdl3Dir = $localSdl
    } else {
        Write-Host "note: no SDL3 found under work\sdl3; pass -Sdl3Dir <path>\cmake (docs/09-TOOLING.md)"
    }
}

$cmakeArgs = @(
    "-S", ".", "-B", "build-render", "-G", "Ninja",
    "-DCMAKE_BUILD_TYPE=Release",
    "-DDREAM_DEV_INTERPRETER=ON", "-DDREAM_RENDERER=ON",
    "-DDREAM_BUILD_TESTS=OFF", "-DDREAM_WERROR=OFF"
)
if ($Sdl3Dir) { $cmakeArgs += "-DSDL3_DIR=$Sdl3Dir" }
# cmd /c receives one string, so an argument with a space (for example an SDL3 path) has to be
# quoted here rather than by the array join.
$cmakeArgLine = ($cmakeArgs | ForEach-Object {
    if ($_ -match '\s') { '"' + $_ + '"' } else { $_ }
}) -join ' '

Push-Location $engine
try {
    cmd /c "`"$vc`" >nul && `"$cmake`" $cmakeArgLine"
    if ($LASTEXITCODE -ne 0) { throw "CMake configure failed ($LASTEXITCODE); see the output above." }
    # dream_render_view renders a capture for the M5 check, so build it with the game; a player
    # never needs it, but the developer checks should not depend on a target setup never built.
    cmd /c "`"$vc`" >nul && `"$cmake`" --build build-render --target draconus_boot dream_render_view --parallel"
    if ($LASTEXITCODE -ne 0) { throw "CMake build failed ($LASTEXITCODE); see the output above." }
} finally {
    Pop-Location
}

$exeDir = Join-Path $engine "build-render\games\draconus"
$exe = Join-Path $exeDir "draconus_boot.exe"
if (-not (Test-Path -LiteralPath $exe)) {
    throw "the build did not produce $exe"
}

# The renderer is optional in the engine's CMake, but this project's player build needs it: without
# Vulkan, SDL3 and glslc the game builds headless and --window refuses to start. Fail here with
# advice instead of printing "built" for a binary that cannot show a picture.
$vkMarker = Join-Path $engine "build-render\render\CMakeFiles\dream_render_vk.dir"
if (-not (Test-Path -LiteralPath $vkMarker)) {
    throw ("the Vulkan renderer was not built. Install the Vulkan SDK (with glslc on PATH) and " +
           "SDL3, then pass -Sdl3Dir <path-to-SDL3Config.cmake-folder>; a build without them " +
           "can only run headless.")
}

# SDL3 is a runtime dependency too, and the launcher scripts expect the DLL next to the executable.
$dll = Join-Path $exeDir "SDL3.dll"
if (-not (Test-Path -LiteralPath $dll)) {
    $candidates = @()
    if ($Sdl3Dir) { $candidates += (Join-Path (Split-Path $Sdl3Dir -Parent) "bin\SDL3.dll") }
    $candidates += (Join-Path $root "work\sdl3\bin\SDL3.dll")
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) {
            Copy-Item -LiteralPath $candidate -Destination $dll
            Write-Host "copied SDL3.dll next to the executable"
            break
        }
    }
}
if (-not (Test-Path -LiteralPath $dll)) {
    throw ("SDL3.dll is missing next to $exe. Pass -Sdl3Dir <path>\cmake where the SDL3 " +
           "package has bin\SDL3.dll, or copy SDL3.dll beside the executable.")
}

# dream_render_view loads SDL3 too, and lives in render\ rather than beside the game, so it needs
# its own copy for m5-check.ps1 to run it.
$viewDir = Join-Path $engine "build-render\render"
$viewDll = Join-Path $viewDir "SDL3.dll"
if ((Test-Path -LiteralPath $viewDir) -and -not (Test-Path -LiteralPath $viewDll)) {
    Copy-Item -LiteralPath $dll -Destination $viewDll
    Write-Host "copied SDL3.dll next to dream_render_view"
}

Write-Host "`nbuilt: engine\build-render\games\draconus\draconus_boot.exe"
Write-Host "       engine\build-render\render\dream_render_view.exe"
Write-Host "run:   .\play-draconus.bat"
